import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.some.js";
import SnackBar from "@/components/SnackBar.vue";
import { list_all_suppliers } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SuplierTransaction from "./popups/SuplierTransaction.vue";
import { format_Date } from "@/JsonFiles/DateFormate.js";
export default {
  components: {
    SnackBar,
    SuplierTransaction
  },
  data() {
    return {
      searchlist: "",
      fixed: true,
      supplierLoading: false,
      supplierData: [],
      next_token: null,
      componentCheck: 0,
      supplierHeight: 0,
      SuplierDetails: false,
      giveGotTransaction: false,
      SuplierData: {},
      SnackBarComponent: {},
      totalPayable: "",
      totalPurchase: "",
      purchase_payment_Type: "",
      indexKey: 0
    };
  },
  async mounted() {
    this.supplierHeight = window.innerHeight - 260;
    await this.fetch_supliers();
  },
  computed: {
    filteredSuppliers() {
      if (!this.searchlist) {
        return this.supplierData;
      }
      return this.supplierData.filter(item => Object.values(item).some(value => String(value).toLowerCase().includes(this.searchlist.toLowerCase())));
    }
  },
  methods: {
    ViewSupplierDetails(item) {
      this.SuplierData = {}; // reset first if needed
      this.indexKey += 1; // force re-render
      this.SuplierData = item;
      this.SuplierDetails = true;
      this.fetch_supliers();
    },
    getLightTransparentColor(index) {
      const colors = ["rgba(244, 67, 54, 0.2)", "rgba(233, 30, 99, 0.2)", "rgba(156, 39, 176, 0.2)", "rgba(63, 81, 181, 0.2)", "rgba(33, 150, 243, 0.2)", "rgba(0, 188, 212, 0.2)", "rgba(76, 175, 80, 0.2)", "rgba(255, 235, 59, 0.2)", "rgba(255, 152, 0, 0.2)", "rgba(121, 85, 72, 0.2)"];
      return colors[index % colors.length];
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.supplierData = [];
      this.giveGotTransaction = false;
      this.next_token = null;
      this.fetch_supliers();
    },
    open_yougot(item) {
      this.SuplierDetails = item;
      this.purchase_payment_Type = "payment_type";
      this.componentCheck = 2;
      this.giveGotTransaction = true;
    },
    open_yougave(item) {
      this.SuplierDetails = item;
      this.purchase_payment_Type = "purchase_type";
      this.componentCheck = 2;
      this.giveGotTransaction = true;
    },
    closeDialog() {
      this.SuplierDetails = false;
      this.fetch_supliers();
    },
    handleClick(item) {
      this.componentCheck = 1;
      this.SuplierDetails = true;
      this.SuplierData = item;
    },
    get_updatedate(date) {
      if (date != "" && date != undefined) {
        return format_Date(date);
      }
    },
    async fetch_supliers() {
      this.supplierLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_all_suppliers, {
          input: {
            nextToken: this.next_token,
            limit: 100
          }
        }));
        this.supplierLoading = false;
        let response = JSON.parse(result.data.list_all_suppliers);
        if (response.Status == "SUCCESS") {
          this.supplierData = response.data;
          // console.log("response",this.supplierData)
          this.totalPayable = response.totalPayable;
          this.totalPurchase = response.totalCumulativePurchased;
          this.next_token = response.nextTokenResponse;
        } else {
          this.supplierData = [];
          this.totalPayable = 0;
          this.next_token = null;
        }
      } catch (error) {
        this.supplierLoading = false;
        this.supplierData = [];
        this.next_token = null;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
